def gen(rng):
    def fmt(ps):
        return (str(len(ps)) + '\n' + ' '.join(str(a) for a, _ in ps) + '\n' + ' '.join(str(b) for _, b in ps))

    def iv(lo, hi, maxlen):
        a = rng.randint(lo, hi)
        return (a, min(hi, a + rng.randint(0, maxlen)))

    tests = [fmt([(5, 5)]), fmt([(0, 0), (0, 0)]), fmt([(1, 5), (5, 9), (9, 12)]), fmt([(0, 5), (10, 15), (20, 25)]),
             fmt([(0, 10 ** 6), (0, 10 ** 6), (0, 10 ** 6)]), fmt([(1, 2), (3, 4)]), fmt([(1, 2), (2, 3)]),
             fmt([(10, 20), (12, 18), (15, 45), (40, 50), (41, 42)])]
    for n in (2, 3, 4, 5, 6, 8, 10, 14):
        for _ in range(3):
            tests.append(fmt([iv(0, rng.choice((10, 30, 100)), rng.choice((0, 3, 10))) for _ in range(n)]))
    N = 100000
    tests.append(fmt([iv(0, 10 ** 6, 100) for _ in range(N)]))
    tests.append(fmt([iv(0, 10 ** 6, 10 ** 6) for _ in range(N)]))
    tests.append(fmt([(10 * i, 10 * i + 5) for i in range(N)]))
    tests.append(fmt([(i, 10 ** 6 - i) for i in range(N)]))
    tests.append(fmt([(7, 7)] * N))
    return tests

